PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS stocks(stock_id TEXT PRIMARY KEY,ticker TEXT NOT NULL,market TEXT NOT NULL,name TEXT NOT NULL,industry TEXT,updated_at TEXT NOT NULL,UNIQUE(market,ticker));
CREATE TABLE IF NOT EXISTS sources(source_id TEXT PRIMARY KEY,provider TEXT NOT NULL,url TEXT,license_type TEXT);
CREATE TABLE IF NOT EXISTS documents(document_id TEXT PRIMARY KEY,source_id TEXT REFERENCES sources(source_id),external_id TEXT,doc_type TEXT NOT NULL,title TEXT NOT NULL,content TEXT NOT NULL DEFAULT '',published_at TEXT NOT NULL,available_at TEXT NOT NULL,ingested_at TEXT NOT NULL,content_hash TEXT NOT NULL,UNIQUE(source_id,external_id));
CREATE TABLE IF NOT EXISTS document_stocks(document_id TEXT NOT NULL REFERENCES documents(document_id),stock_id TEXT NOT NULL REFERENCES stocks(stock_id),relevance REAL,PRIMARY KEY(document_id,stock_id));
CREATE TABLE IF NOT EXISTS financial_metrics(stock_id TEXT NOT NULL REFERENCES stocks(stock_id),metric TEXT NOT NULL,period_end TEXT NOT NULL,period_type TEXT NOT NULL,value REAL NOT NULL,unit TEXT,available_at TEXT NOT NULL,PRIMARY KEY(stock_id,metric,period_end,period_type));
CREATE TABLE IF NOT EXISTS chip_metrics(stock_id TEXT NOT NULL REFERENCES stocks(stock_id),trade_date TEXT NOT NULL,metric TEXT NOT NULL,value REAL NOT NULL,unit TEXT,PRIMARY KEY(stock_id,trade_date,metric));
CREATE TABLE IF NOT EXISTS graph_nodes(node_id TEXT PRIMARY KEY,node_type TEXT NOT NULL,label TEXT NOT NULL,stock_id TEXT REFERENCES stocks(stock_id),document_id TEXT REFERENCES documents(document_id),properties_json TEXT NOT NULL DEFAULT '{}',updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS embedding_models(model_id TEXT PRIMARY KEY,model_name TEXT NOT NULL,dimension INTEGER NOT NULL,config_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS embeddings(node_id TEXT NOT NULL REFERENCES graph_nodes(node_id),model_id TEXT NOT NULL REFERENCES embedding_models(model_id),content_hash TEXT NOT NULL,vector BLOB NOT NULL,computed_at TEXT NOT NULL,PRIMARY KEY(node_id,model_id));
CREATE TABLE IF NOT EXISTS graph_edges(edge_id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES graph_nodes(node_id),target_id TEXT NOT NULL REFERENCES graph_nodes(node_id),relation_type TEXT NOT NULL,method TEXT NOT NULL,score REAL,model_id TEXT REFERENCES embedding_models(model_id),as_of TEXT NOT NULL,properties_json TEXT NOT NULL DEFAULT '{}',CHECK(source_id<>target_id));
CREATE TABLE IF NOT EXISTS edge_evidence(edge_id TEXT NOT NULL REFERENCES graph_edges(edge_id) ON DELETE CASCADE,document_id TEXT NOT NULL REFERENCES documents(document_id),PRIMARY KEY(edge_id,document_id));
CREATE TABLE IF NOT EXISTS pipeline_runs(run_id INTEGER PRIMARY KEY AUTOINCREMENT,started_at TEXT NOT NULL,finished_at TEXT,status TEXT NOT NULL,details TEXT);
CREATE INDEX IF NOT EXISTS idx_document_stocks_stock ON document_stocks(stock_id);
CREATE INDEX IF NOT EXISTS idx_documents_available ON documents(available_at);
CREATE INDEX IF NOT EXISTS idx_financial_stock_period ON financial_metrics(stock_id,period_end);
CREATE INDEX IF NOT EXISTS idx_chip_stock_date ON chip_metrics(stock_id,trade_date);
CREATE INDEX IF NOT EXISTS idx_nodes_stock ON graph_nodes(stock_id);
CREATE INDEX IF NOT EXISTS idx_edges_source ON graph_edges(source_id,relation_type);
CREATE INDEX IF NOT EXISTS idx_edges_target ON graph_edges(target_id,relation_type);
CREATE TABLE IF NOT EXISTS similarity_state(model_id TEXT PRIMARY KEY REFERENCES embedding_models(model_id),input_hash TEXT NOT NULL,edge_hash TEXT NOT NULL,stats_json TEXT NOT NULL);
